SoloCDM wrote:
> How are there four (/bin/dnsdomainname /bin/domainname
> /bin/nisdomainname /bin/ypdomainname) different types of hostname
> links with their own separate options?The program has different behaviour depending on the value of
argv[0], probably...here's a simple example...#include 
#include 
#include long int add(long int a, long int b)
{
  return a+b;
}long int subtract(long int a, long int b)
{
  return a-b;
}int main(int argc, char **argv)
{
  long int a, b; /* Operands */
  long int (*operation)(long int a, long int b);
  char *progname, *marker;  if(argc != 3)
  {
    fprintf(stderr, "Usage: %s [int1] [int2]\n", argv[0]);
    exit(1);
  }  progname = strrchr(argv[0], '/');
  if(progname == NULL)
    progname = argv[0];
  else
    progname ++; /* Skip past the '/' */

  if(strcmp(progname, "add") == 0)
  {
    operation = add;
  }
  else if (strcmp(progname, subtract) == 0)
  {
    operation = subtract;
  }
  else
  {
    fprintf(stderr, "Program called with invalid "
            "name %s. Quitting.\n", argv[0]);
    exit(1);
  }  a = strtol(argv[1], &marker, 0); /* Use base 16 for args
                                    * starting 0x, and base 8 for 
                                    * args starting 0 */
  if(*marker != '\0')
  {
    fprintf(stderr, "Invalid character %c in argument %s.\n",
            *marker, argv[1]);
    exit(1);
  }  b = strtol(argv[2], &marker, 0); /* Use base 16 for args
                                    * starting 0x, and base 8 for 
                                    * args starting 0 */
  if(*marker != '\0')
  {
    fprintf(stderr, "Invalid character %c in argument %s.\n",
            *marker, argv[2]);
    exit(1);
  }

  printf("%ld %c %ld = %ld\n", 
          a, 
          (operation == add)?'+':'-', 
          b, 
          operation(a, b));

  return 0;
}Say that's in operation.c, compile it using gcc -ansi -pedantic -Wall -W -O2 -o add operation.c
and then 
ln add subtract
and run both, with appropriate arguments.-- 
       David Neary,
    Marseille, France
